p='src/server/repositories/activity-repository.ts'
s=open(p).read()
s=s.replace('''import { and, count, desc, eq, gte, inArray, lt } from "drizzle-orm";''','''import { and, count, desc, eq, gte, inArray, lt, lte } from "drizzle-orm";''')
s=s.replace('''import type { ActivityEvent, ActivitySubjectKind } from "@/types/activity";
import type { IsoTimestamp, OrgId, Page } from "@/types/common";''','''import { toIsoTimestamp } from "@/types/common";
import type { ActivityEvent, ActivitySubjectKind } from "@/types/activity";
import type { IsoTimestamp, OrgId, Page } from "@/types/common";
import type { SQL } from "drizzle-orm";

/** The filter half of `ActivityFilterInput`, without the paging fields. */
export type ActivityRangeFilter = Omit<ActivityFilterInput, "limit" | "cursor">;''')
s=s.replace('''      summary: event.summary,
      // The summary is the audited fact; the scalar bag is presentation-only
      // and is reconstructed by the readers that need it.
      metadata: "{}",
      occurredAt: event.occurredAt,''','''      summary: event.summary,
      metadata: JSON.stringify(event.metadata ?? {}),
      // Stored in the canonical ISO form so the text column sorts and
      // compares chronologically.
      occurredAt: toIsoTimestamp(event.occurredAt),''')
old=s[s.index('export async function listActivity('):s.index('/** The "history" tab')]
new='''/**
 * Predicates shared by the paged feed and the export. The time range is closed
 * on both ends; the bounds are normalised to the stored ISO form first, so an
 * equivalent spelling of the same instant compares equal.
 */
function activityFilters(input: ActivityRangeFilter): readonly SQL[] {
  return compact(
    orgPredicate(activityEvents.orgId, input.orgId),
    input.action === undefined || input.action.length === 0
      ? undefined
      : inArray(activityEvents.action, [...input.action]),
    input.actorId === undefined
      ? undefined
      : eq(activityEvents.actorId, input.actorId),
    input.projectId === undefined
      ? undefined
      : eq(activityEvents.projectId, input.projectId),
    input.subjectKind === undefined
      ? undefined
      : eq(activityEvents.subjectKind, input.subjectKind),
    input.since === undefined
      ? undefined
      : gte(activityEvents.occurredAt, toIsoTimestamp(input.since)),
    input.until === undefined
      ? undefined
      : lte(activityEvents.occurredAt, toIsoTimestamp(input.until)),
  );
}

export async function listActivity(
  input: ActivityFilterInput,
): Promise<Page<ActivityEvent>> {
  const db = getDb();
  const sort = {
    sortColumn: activityEvents.occurredAt,
    idColumn: activityEvents.id,
  };

  const filters = activityFilters(input);

  const total = db
    .select({ value: count() })
    .from(activityEvents)
    .where(and(...filters))
    .get();

  const rows = db
    .select()
    .from(activityEvents)
    .where(and(...filters, ...compact(keysetPredicate(sort, input.cursor))))
    .orderBy(desc(activityEvents.occurredAt), desc(activityEvents.id))
    .limit(probeLimit(input.limit))
    .all();

  return toPage(
    rows,
    input.limit,
    total?.value ?? 0,
    toActivityEvent,
    (row) => ({ id: row.id, sortValue: row.occurredAt }),
  );
}

/**
 * Every matching row, newest first, in one read — the export must be
 * complete however large the range is, which the capped feed page is not.
 */
export async function listAllActivity(
