new='''/**
 * Predicates shared by the paged feed and the export. The time range is closed
 * on both ends; the bounds are normalised to the stored ISO form first, so an
 * equivalent spelling of the same instant compares equal.
 */
function activityFilters(input: ActivityRangeFilter): readonly SQL[] {
  return compact(
    orgPredicate(activityEvents.orgId, input.orgId),
    input.action === undefined || input.action.length === 0
      ? undefined
      : inArray(activityEvents.action, [...input.action]),
    input.actorId === undefined
      ? undefined
      : eq(activityEvents.actorId, input.actorId),
    input.projectId === undefined
      ? undefined
      : eq(activityEvents.projectId, input.projectId),
    input.subjectKind === undefined
      ? undefined
      : eq(activityEvents.subjectKind, input.subjectKind),
    input.since === undefined
      ? undefined
      : gte(activityEvents.occurredAt, toIsoTimestamp(input.since)),
    input.until === undefined
      ? undefined
      : lte(activityEvents.occurredAt, toIsoTimestamp(input.until)),
  );
}

export async function listActivity(
  input: ActivityFilterInput,
): Promise<Page<ActivityEvent>> {
  const db = getDb();
  const sort = {
    sortColumn: activityEvents.occurredAt,
    idColumn: activityEvents.id,
  };

  const filters = activityFilters(input);

  const total = db
    .select({ value: count() })
    .from(activityEvents)
    .where(and(...filters))
    .get();

  const rows = db
    .select()
    .from(activityEvents)
    .where(and(...filters, ...compact(keysetPredicate(sort, input.cursor))))
    .orderBy(desc(activityEvents.occurredAt), desc(activityEvents.id))
    .limit(probeLimit(input.limit))
    .all();

  return toPage(
    rows,
    input.limit,
    total?.value ?? 0,
    toActivityEvent,
    (row) => ({ id: row.id, sortValue: row.occurredAt }),
  );
}

/**
 * Every matching row, newest first, in one read — the export must be
 * complete however large the range is, which the capped feed page is not.
 */
export async function listAllActivity(
  input: ActivityRangeFilter,
): Promise<readonly ActivityEvent[]> {
  const rows = getDb()
    .select()
    .from(activityEvents)
    .where(and(...activityFilters(input)))
    .orderBy(desc(activityEvents.occurredAt), desc(activityEvents.id))
    .all();

  return rows.map(toActivityEvent);
}

