import type { Tenant } from "#t/server/_support/fixtures";

let cleanup: () => void;
let t: Tenant;
let off: () => void;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  t = await createTenant("chk", "growth");
  off = activity.registerActivityListeners();
});
afterAll(() => { off(); cleanup(); });

async function all(filter: Record<string, unknown> = {}) {
  const items = [];
  let cursor: string | null = null;
  do {
    const page = await activity.listActivity(t.actors.owner, { orgId: t.org.id, limit: 100, cursor, ...filter } as never);
