}

describe("activity", () => {
  it("records every action once, with actor & project", async () => {
    const other = await projectRepo.insertProject({
      orgId: t.org.id, name: "Other", slug: "other", key: "OTH", description: null,
      visibility: "org", leadId: t.userIds.owner, color: "#6366f1", targetDate: null,
    });
    const otherIssue = await issueService.createIssue(t.actors.member, issueInput(t.org.id, other.id, { title: "Other issue" }));
    await issueService.changeIssueStatus(t.actors.member, { orgId: t.org.id, issueId: otherIssue.id, status: "todo" });

    const issue = await issueService.createIssue(t.actors.member, issueInput(t.org.id, t.project.id, { title: "Main issue" }));
    await issueService.updateIssue(t.actors.member, { orgId: t.org.id, issueId: issue.id, title: "Main issue 2" });
    await issueService.changeIssueStatus(t.actors.member, { orgId: t.org.id, issueId: issue.id, status: "in_progress" });
    await issueService.assignIssue(t.actors.admin, { orgId: t.org.id, issueId: issue.id, assigneeId: t.userIds.member });
    const c = await commentService.createComment(t.actors.member, { orgId: t.org.id, issueId: issue.id, body: "hi", parentId: null, mentionedUserIds: [] } as never);
    await commentService.updateComment(t.actors.member, { orgId: t.org.id, commentId: c.id, body: "hello" });
    await commentService.deleteComment(t.actors.member, { orgId: t.org.id, commentId: c.id });
