    await projectService.updateProject(t.actors.owner, { orgId: t.org.id, projectId: t.project.id, name: "Renamed" });
    await projectService.archiveProject(t.actors.owner, { orgId: t.org.id, projectId: t.project.id, archiveIssues: true });
