    const inProject = await all({ projectId: t.project.id });
    const actions = inProject.map((e) => e.action).sort();
    expect(actions).toEqual([
      "comment.created", "comment.deleted", "comment.updated",
      "issue.archived", "issue.assigned", "issue.created", "issue.status_changed", "issue.updated",
      "project.archived", "project.restored", "project.updated",
    ].sort());
    const assigned = inProject.find((e) => e.action === "issue.assigned");
    expect(assigned?.actorId).toBe(t.userIds.admin);
    const status = inProject.find((e) => e.action === "issue.status_changed");
    expect(status?.metadata).toEqual({ from: "backlog", to: "in_progress" });
