    await memberService.updateMemberRole(t.actors.owner, { orgId: t.org.id, memberId: viewer.id, role: "member" });
    await memberService.removeMember(t.actors.owner, { orgId: t.org.id, memberId: viewer.id });
    await flagService.toggleFlag(t.actors.owner, { orgId: t.org.id, flag: "kanban_board", enabled: true } as never);
    await orgService.updateOrganization(t.actors.owner, { orgId: t.org.id, name: "Chk renamed" });
    await billingService.changePlan(t.actors.owner, { orgId: t.org.id, plan: "business", interval: "monthly" } as never);
    const u = await userRepo.insertUser({ email: "o2@chk.test", name: "o2", passwordHash: "x" });
    const org2 = await orgService.createOrganization(u.id, { name: "Org two", slug: "org-two", plan: "free" });

    const everything = await all();
    const count = (a: string) => everything.filter((e) => e.action === a).length;
    for (const a of ["member.invited", "member.role_changed", "member.removed", "flag.toggled", "organization.updated", "billing.plan_changed"]) {
      expect(count(a), a).toBe(1);
    }
    expect(everything.every((e) => e.actorId !== null)).toBe(true);
    const joined = await activity.listActivity({ userId: u.id, orgId: org2.id, role: "owner" }, { orgId: org2.id, limit: 10, cursor: null } as never);
    expect(joined.items.map((e) => e.action)).toEqual(["member.joined"]);
