    expect(r.items).toHaveLength(1);
    expect(r.items[0]?.occurredAt).toBe(past);
    const r2 = await activity.listActivity(t.actors.owner, { orgId: t.org.id, since: "2020-05-05T10:00:00Z", until: "2020-05-05T10:00:00Z", limit: 10, cursor: null } as never);
    expect(r2.items).toHaveLength(1);
    await expect(activity.listActivity(t.actors.owner, { orgId: t.org.id, since: "2020-05-06T00:00:00.000Z", until: past, limit: 10, cursor: null } as never)).rejects.toThrow();
    await expect(activity.exportActivity(t.actors.owner, { orgId: t.org.id, since: "2020-05-06T00:00:00.000Z", until: past, format: "json" } as never)).rejects.toThrow();
    const exp = JSON.parse(await activity.exportActivity(t.actors.owner, { orgId: t.org.id, since: past, until: past, format: "json" } as never));
    expect(exp).toHaveLength(1);
    expect(exp[0].metadata).toEqual({ from: "free", to: "growth" });
  });

  it("exports everything in range", async () => {
    const other = await createTenant("chk-other", "growth");
    const base = Date.parse("2021-01-01T00:00:00.000Z");
    for (let i = 0; i < 250; i++) {
      const at = new Date(base + Math.floor(i / 3) * 1000).toISOString();
      await emit("flag.toggled", { orgId: t.org.id, actorId: t.userIds.owner, occurredAt: at as never, flag: "kanban_board", enabled: i % 2 === 0 });
      await emit("flag.toggled", { orgId: other.org.id, actorId: other.userIds.owner, occurredAt: at as never, flag: "kanban_board", enabled: true });
    }
    const end = new Date(base + Math.floor(249 / 3) * 1000).toISOString();
    const exp = JSON.parse(await activity.exportActivity(t.actors.owner, { orgId: t.org.id, since: "2021-01-01T00:00:00.000Z", until: end, format: "json" } as never));
    expect(exp).toHaveLength(250);
    expect(new Set(exp.map((e: { id: string }) => e.id)).size).toBe(250);
    expect(exp.every((e: { orgId: string }) => e.orgId === t.org.id)).toBe(true);
    for (let i = 1; i < exp.length; i++) expect(exp[i - 1].occurredAt >= exp[i].occurredAt).toBe(true);
    const csv = await activity.exportActivity(t.actors.owner, { orgId: t.org.id, since: "2021-01-01T00:00:00.000Z", until: end, format: "csv" } as never);
    expect(csv.trim().split("\n")).toHaveLength(251);
  });
});
